def solve(I):
    H,W=len(I),len(I[0])
    cnt=Counter(x for r in I for x in r); bg=cnt.most_common(1)[0][0]
    specials=[v for v in cnt if v!=bg]
    sb=min(specials,key=lambda c:cnt[c])          # blocker (rare)
    sc=max(specials,key=lambda c:cnt[c])          # fill color
    badrows={i for i in range(H) for j in range(W) if I[i][j]==sb}
    badcols={j for i in range(H) for j in range(W) if I[i][j]==sb}
    return [[I[i][j] if I[i][j]!=bg else (sc if (i not in badrows and j not in badcols) else 2) for j in range(W)] for i in range(H)]
for n in [1,2,3,4,5,6]:
    k='Demo pair %d'%n
    print(k, solve(G[k+' input'])==G[k+' output'])
